using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using OfficeIMO.Drawing;
using OfficeIMO.Html;
using OfficeIMO.Html.Pdf;
using OfficeIMO.Pdf;

// This probe records public observations. Fixture acceptance belongs to a later,
// reviewed contract; no source-token count or expected placement is assumed here.
if (args.Length is < 3 or > 4)
    throw new ArgumentException("Usage: DescendantSpannerProbe <input.html> <new-output> <runtime-binding.json> [font-directory]");
string input = Path.GetFullPath(args[0]), output = Path.GetFullPath(args[1]);
string bindingPath = Path.GetFullPath(args[2]);
string fontDirectory = args.Length == 4 ? Path.GetFullPath(args[3]) : Path.GetDirectoryName(input)!;
if (Directory.Exists(output) || File.Exists(output))
    throw new IOException("Preserve existing evidence; supply a new output directory.");
byte[] bindingBytes = File.ReadAllBytes(bindingPath);
using var bindingFile = JsonDocument.Parse(bindingBytes);
JsonElement binding = bindingFile.RootElement;
VerifyBinding(binding);
byte[] html = File.ReadAllBytes(input);
string regularPath = Path.Combine(fontDirectory, "regular.ttf"), boldPath = Path.Combine(fontDirectory, "bold.ttf");
byte[] regular = File.ReadAllBytes(regularPath), bold = File.ReadAllBytes(boldPath);
using var zipBytes = new MemoryStream();
using (var zip = new ZipArchive(zipBytes, ZipArchiveMode.Create, true)) {
    foreach (var entry in new[] { ("index.html", html), ("regular.ttf", regular), ("bold.ttf", bold) }) {
        var item = zip.CreateEntry(entry.Item1);
        item.LastWriteTime = new DateTimeOffset(2020, 1, 1, 0, 0, 0, TimeSpan.Zero);
        using var stream = item.Open();
        stream.Write(entry.Item2);
    }
}
zipBytes.Position = 0;
HtmlSiteBundle bundle = HtmlSiteBundle.Load(zipBytes);
Directory.CreateDirectory(output);
var rows = new List<object>();
foreach (var profile in new[] { HtmlRenderIntentProfile.PrintPaged, HtmlRenderIntentProfile.ScreenMediaPaged,
             HtmlRenderIntentProfile.ScreenFullPage, HtmlRenderIntentProfile.ScreenSnapshotPaged }) {
    var options = new HtmlToPdfOptions {
        ViewportWidth = 800, ViewportHeight = 1000,
        PageSize = new OfficePageSize(800D / 96D, 1000D / 96D), Margins = HtmlRenderMargins.All(0),
        HonorCssPageRules = true, DefaultFontFamily = "Witness", DefaultFontSize = 14,
        AllowSystemFontFallback = false, ResourcePolicy = PdfResourcePolicy.CreatePortableDeterministic(),
        UserAgentStyles = HtmlRenderUserAgentStyleMode.Browser,
        FontFamily = new PdfEmbeddedFontFamily("Witness", regular, bold)
    };
    options.Fonts.Add("Witness", regular);
    options.Fonts.Add("Witness", bold, OfficeFontStyle.Bold);
    var result = HtmlRenderEngine.Execute(bundle.HtmlDocument,
        bundle.CreateRenderRequest(HtmlRenderRequest.Create(profile, HtmlRenderEncoder.Png, options)));
    var images = result.ExportImages();
    Require(images.Count == result.Document.Pages.Count, profile + ": public PNG/surface count mismatch");
    var imageObservations = new List<object>();
    for (int page = 0; page < images.Count; page++) {
        byte[] png = images[page].Bytes;
        byte[] scenePng = OfficeRasterImageEncoder.Encode(
            OfficeDrawingRasterRenderer.Render(result.Document.Pages[page].CreateDrawing()), OfficeImageExportFormat.Png);
        string pngName = $"{profile}-{page + 1:D2}.png", sceneName = $"{profile}-{page + 1:D2}-scene.png";
        File.WriteAllBytes(Path.Combine(output, pngName), png);
        File.WriteAllBytes(Path.Combine(output, sceneName), scenePng);
        imageObservations.Add(new { page = page + 1, png = Artifact(pngName, png),
            scenePng = Artifact(sceneName, scenePng), publicPngEqualsScenePng = png.SequenceEqual(scenePng) });
    }
    bool? parity = null;
    object? pdfObservation = null;
    if (profile != HtmlRenderIntentProfile.ScreenFullPage) {
        byte[] pdf = bundle.RenderToPdfResult(HtmlRenderRequest.Create(profile, HtmlRenderEncoder.Pdf, options)).ToBytes();
        string pdfName = profile + ".pdf";
        File.WriteAllBytes(Path.Combine(output, pdfName), pdf);
        var reopened = PdfReadDocument.Open(pdf);
        var replay = reopened.ExportImages(OfficeImageExportFormat.Png, new PdfImageExportOptions { Scale = 96D / 72D });
        parity = images.Count == replay.Count && !images.Where((image, page) => !image.Bytes.SequenceEqual(replay[page].Bytes)).Any();
        Require(parity == true, profile + ": PNG/PDF replay mismatch");
        var replayArtifacts = new List<object>();
        for (int page = 0; page < replay.Count; page++) {
            string name = $"{profile}-{page + 1:D2}-pdf-replay.png";
            File.WriteAllBytes(Path.Combine(output, name), replay[page].Bytes);
            replayArtifacts.Add(Artifact(name, replay[page].Bytes));
        }
        pdfObservation = new { artifact = Artifact(pdfName, pdf), replay = replayArtifacts,
            pages = reopened.Pages.Select((page, index) => new { page = index + 1,
                text = page.GetTextSpans().Select(text => new { text.Text, text.X, text.Y, text.Advance,
                    text.FontSize, text.FontResource, text.BaseFont, text.FontWeight, text.IsVisible,
                    text.HasActualText, text.IsArtifactContent, text.RotationDegrees }).ToArray(),
                links = page.GetLinkAnnotations().Select(link => new { link.PageNumber, link.Uri,
                    link.DestinationName, link.DestinationPageNumber, link.DestinationTop, link.DestinationLeft,
                    link.DestinationBottom, link.DestinationRight, link.DestinationMode,
                    link.X1, link.Y1, link.X2, link.Y2 }).ToArray() }).ToArray(),
            destinations = reopened.NamedDestinations.Select(destination => new { destination.Name,
                destination.PageNumber, destination.DestinationTop, destination.DestinationLeft,
                destination.DestinationBottom, destination.DestinationRight, destination.DestinationMode }).ToArray() };
    }
    var svgResult = HtmlRenderEngine.Execute(bundle.HtmlDocument,
        bundle.CreateRenderRequest(HtmlRenderRequest.Create(profile, HtmlRenderEncoder.Svg, options)));
    var svgs = svgResult.ExportImages();
    Require(svgs.Count == images.Count, profile + ": SVG/PNG surface count mismatch");
    var svgArtifacts = new List<object>();
    for (int page = 0; page < svgs.Count; page++) {
        string name = $"{profile}-{page + 1:D2}.svg";
        File.WriteAllBytes(Path.Combine(output, name), svgs[page].Bytes);
        svgArtifacts.Add(Artifact(name, svgs[page].Bytes));
    }
    bool requireNoLossThrows = false;
    try { result.Document.RequireNoLoss(); } catch (HtmlConversionException) { requireNoLossThrows = true; }
    rows.Add(new { profile = profile.ToString(), pages = images.Count, parity,
        pageGeometry = result.Document.Pages.Select(page => new { page.Width, page.Height }).ToArray(),
        documentText = result.Document.Text,
        documentWords = result.Document.Text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries),
        mode = result.Document.Mode.ToString(), result.Document.HasLoss, requireNoLossThrows,
        scene = result.Document.Pages.Select(ObservePage).ToArray(),
        diagnostics = result.Document.Diagnostics.Select(diagnostic => new { diagnostic.Code,
            diagnostic.Severity, diagnostic.LossKind, diagnostic.Component, diagnostic.Message,
            diagnostic.Source, diagnostic.Detail, diagnostic.Provenance }).ToArray(),
        svgDiagnostics = svgResult.Document.Diagnostics.Select(diagnostic => new { diagnostic.Code,
            diagnostic.Severity, diagnostic.LossKind, diagnostic.Component, diagnostic.Message,
            diagnostic.Source, diagnostic.Detail, diagnostic.Provenance }).ToArray(),
        images = imageObservations, svg = svgArtifacts, pdf = pdfObservation });
}
VerifyBinding(binding);
Require(Hash(File.ReadAllBytes(bindingPath)) == Hash(bindingBytes), "Runtime binding changed during capture");
Require(File.ReadAllBytes(input).SequenceEqual(html) && File.ReadAllBytes(regularPath).SequenceEqual(regular)
    && File.ReadAllBytes(boldPath).SequenceEqual(bold), "Input/font bytes changed during capture");
File.WriteAllText(Path.Combine(output, "summary.json"), JsonSerializer.Serialize(new {
    schema = "officeimo.html.descendant-spanner-observations/v1",
    inputSha256 = Hash(html), regularSha256 = Hash(regular), boldSha256 = Hash(bold), bundleSha256 = Hash(zipBytes.ToArray()),
    input = Metadata(input), regular = Metadata(regularPath), bold = Metadata(boldPath),
    sourceHead = binding.GetProperty("sourceHead").GetString(), sourceManifest = binding.GetProperty("sourceManifest"),
    producerAssembly = binding.GetProperty("producerAssembly"), probeSources = binding.GetProperty("probeSources"),
    runtime = binding.GetProperty("runtimeDlls"), runtimeBinding = Metadata(bindingPath), rows,
    resourceBoundary = "Bounded ZIP bundle supplies exact Witness fonts; system fallback disabled; portable deterministic PDF resources",
    coordinateBoundary = "CSS pixel surface coordinates with explicit ancestor effect transforms; owning glyph carriers are not clipped visible-ink rectangles",
    proofBoundary = "Public observations only. Exact deployed runtime bytes are bound to the controller's source/build receipt; no case acceptance or native-equivalence claim."
}, new JsonSerializerOptions { WriteIndented = true }));
Console.WriteLine("Recorded four-profile public observations and exact PNG/PDF replay for the three PDF profiles.");

static object ObservePage(HtmlRenderPage page) {
    SceneItem[] all = Walk(page.Scene, OfficeTransform.Identity, "", true).ToArray();
    return new { page.PageNumber, page.PageName, page.Width, page.Height, page.Margins,
        text = all.Where(item => item.OwnsSource && item.Visual is HtmlRenderText { Text.Length: > 0 }).Select(ObserveText).ToArray(),
        cells = all.Where(item => item.Visual is HtmlRenderSemanticGroup {
            Role: HtmlRenderSemanticGroupRole.TableCell or HtmlRenderSemanticGroupRole.TableHeaderCell })
            .Select(item => { var group = (HtmlRenderSemanticGroup)item.Visual;
                return new { group.Source, group.X, group.Y, group.Width, group.Height, group.RowSpan, group.ColumnSpan, item.Path }; }).ToArray(),
        visuals = all.Select(ObserveVisual).ToArray(),
        links = all.Where(item => item.Visual.LinkUri is not null).Select(ObserveVisual).ToArray(),
        shapes = all.Where(item => item.Visual is HtmlRenderShape).Select(ObserveVisual).ToArray(),
        clips = all.Where(item => item.Visual is HtmlRenderClipGroup or HtmlRenderPathClipGroup).Select(ObserveVisual).ToArray(),
        layoutRegions = all.Where(item => item.Visual is HtmlRenderLayoutRegion).Select(ObserveVisual).ToArray(),
        logicalEnvelopes = all.Where(item => item.Visual is HtmlRenderLogicalTextGroup).Select(ObserveVisual).ToArray() };
}

static object ObserveText(SceneItem item) {
    var text = (HtmlRenderText)item.Visual;
    OfficePoint point = item.Transform.TransformPoint(new OfficePoint(text.X, text.Y));
    var bounds = item.Transform.TransformRectangleBounds(text.X, text.Y, text.Width, text.Height);
    return new { text.Text, X = point.X, Y = point.Y,
        Width = bounds.Right - bounds.Left, Height = bounds.Bottom - bounds.Top,
        text.Source, text.LinkUri, text.PaintOrder, text.SemanticRole, text.SemanticNodeId,
        text.LineHeight, text.TextAdvanceWidth, text.TextPaintWidth, text.BaselineOffset, text.BaselineScale,
        font = Font(text.Font), face = Face(text.FontDescriptor), item.Path,
        raw = new { text.X, text.Y, text.Width, text.Height }, transform = Transform(item.Transform) };
}

static IEnumerable<SceneItem> Walk(IEnumerable<HtmlRenderVisual> visuals, OfficeTransform transform, string parentPath, bool ownsSource) {
    int index = 0;
    foreach (HtmlRenderVisual visual in visuals) {
        string path = parentPath.Length == 0 ? index.ToString() : parentPath + "/" + index;
        index++;
        // Canonical source ownership matches the prior package probe. Artifact
        // subtrees and empty logical envelopes paint without another source token.
        bool owned = ownsSource && visual is not HtmlRenderSemanticGroup { Role: HtmlRenderSemanticGroupRole.Artifact }
            && visual is not HtmlRenderLogicalTextGroup { Text.Length: 0 };
        yield return new SceneItem(visual, transform, path, owned);
        IReadOnlyList<HtmlRenderVisual>? children = visual switch {
            HtmlRenderClipGroup clip => clip.Visuals,
            HtmlRenderPathClipGroup clip => clip.Visuals,
            HtmlRenderEffectGroup effect => effect.Visuals,
            HtmlRenderSemanticGroup semantic => semantic.Visuals,
            HtmlRenderLayoutRegion region => region.Visuals,
            HtmlRenderLogicalTextGroup logical => logical.Visuals,
            HtmlRenderFormField field => field.Visuals,
            _ => null
        };
        if (children is null) continue;
        // Group X/Y are already surface coordinates, never child translations.
        OfficeTransform childTransform = visual is HtmlRenderEffectGroup group ? group.Transform.Then(transform) : transform;
        foreach (SceneItem child in Walk(children, childTransform, path, owned)) yield return child;
    }
}

static object ObserveVisual(SceneItem item) {
    HtmlRenderVisual visual = item.Visual;
    OfficePoint point = item.Transform.TransformPoint(new OfficePoint(visual.X, visual.Y));
    var bounds = item.Transform.TransformRectangleBounds(visual.X, visual.Y, visual.Width, visual.Height);
    object? detail = visual switch {
        HtmlRenderText text => new { text.Text, font = Font(text.Font), face = Face(text.FontDescriptor),
            text.LineHeight, text.TextAdvanceWidth, text.TextPaintWidth, text.BaselineOffset, text.SemanticRole, text.SemanticNodeId },
        HtmlRenderClipGroup clip => new { clip.ClipX, clip.ClipY, clip.ClipWidth, clip.ClipHeight, clip.ClipHorizontal, clip.ClipVertical },
        HtmlRenderPathClipGroup clip => new { clip.ClipX, clip.ClipY, path = ClipPath(clip.ClipPath) },
        HtmlRenderEffectGroup effect => new { transform = Transform(effect.Transform), effect.Opacity },
        HtmlRenderSemanticGroup semantic => new { role = semantic.Role.ToString(), semantic.AlternativeText,
            semantic.ColumnSpan, semantic.RowSpan, semantic.HeaderScope },
        HtmlRenderLayoutRegion region => new { region.SourceKey, kind = region.RegionKind.ToString(), region.SourceText,
            region.Position, region.FloatSide, region.ZIndex, region.BackgroundLayerCount, region.BoxShadowLayerCount,
            backgroundColor = region.BackgroundColor?.ToString(), region.SurfaceNumber, region.SemanticSectionNumber, region.SemanticTableNumber },
        HtmlRenderLogicalTextGroup logical => new { logical.Text },
        HtmlRenderFormField field => new { kind = field.FieldKind.ToString(), field.Name, field.Value, field.Values,
            field.Options, field.SelectedOptionIndices, field.IsSelected, field.IsDisabled, field.IsReadOnly },
        HtmlRenderShape shape => Shape(shape.Shape),
        HtmlRenderBookmarkAnchor anchor => new { anchor.Text, anchor.SemanticNodeId },
        _ => null
    };
    return new { item.Path, kind = visual.Kind.ToString(), visual.Source, visual.LinkUri, visual.PaintOrder,
        visual.X, visual.Y, visual.Width, visual.Height, item.OwnsSource,
        transformed = new { X = point.X, Y = point.Y, Left = bounds.Left, Top = bounds.Top, Right = bounds.Right, Bottom = bounds.Bottom },
        transform = Transform(item.Transform), detail };
}

static object Shape(OfficeShape shape) => new { kind = shape.Kind.ToString(), shape.Width, shape.Height,
    fillColor = shape.FillColor?.ToString(), strokeColor = shape.StrokeColor?.ToString(), shape.StrokeWidth,
    shape.FillOpacity, shape.StrokeOpacity, shape.CornerRadius, fillRule = shape.FillRule.ToString(),
    shape.Points, pathCommands = Commands(shape.PathCommands),
    transform = shape.Transform.HasValue ? Transform(shape.Transform.Value) : null,
    clipPath = shape.ClipPath is null ? null : ClipPath(shape.ClipPath) };
static object ClipPath(OfficeClipPath path) => new { kind = path.Kind.ToString(), path.Width, path.Height,
    path.CornerRadius, fillRule = path.FillRule.ToString(), commands = Commands(path.Commands) };
static object[] Commands(IEnumerable<OfficePathCommand> commands) => commands.Select(command => (object)new {
    kind = command.Kind.ToString(), command.Point, command.ControlPoint1, command.ControlPoint2 }).ToArray();
static object Transform(OfficeTransform transform) => new { transform.M11, transform.M12, transform.M21,
    transform.M22, transform.OffsetX, transform.OffsetY };
static object Font(OfficeFontInfo font) => new { font.FamilyName, font.Size, style = font.Style.ToString() };
static object Face(OfficeFontFaceDescriptor face) => new { face.Weight, face.StretchPercent, slant = face.Slant.ToString(), face.ObliqueAngleDegrees };
static object Artifact(string path, byte[] bytes) => new { path, bytes = bytes.LongLength, sha256 = Hash(bytes) };
static object Metadata(string path) => Artifact(Path.GetFullPath(path), File.ReadAllBytes(path));
static string Hash(byte[] bytes) => Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
static void Require(bool condition, string message) { if (!condition) throw new InvalidDataException(message); }

static void VerifyMetadata(JsonElement value) {
    string path = value.GetProperty("path").GetString()!;
    Require(Path.IsPathFullyQualified(path), "Binding metadata requires absolute paths");
    byte[] bytes = File.ReadAllBytes(path);
    Require(value.GetProperty("bytes").GetInt64() == bytes.LongLength
        && value.GetProperty("sha256").GetString() == Hash(bytes), "Binding bytes changed: " + path);
}

static void VerifyBinding(JsonElement binding) {
    string sourceHead = binding.GetProperty("sourceHead").GetString()!;
    Require(sourceHead.Length == 40 && sourceHead.All(Uri.IsHexDigit), "Exact source head required");
    JsonElement manifest = binding.GetProperty("sourceManifest");
    VerifyMetadata(manifest);
    using var sourceFile = JsonDocument.Parse(File.ReadAllBytes(manifest.GetProperty("path").GetString()!));
    Require(sourceFile.RootElement.GetProperty("headSha").GetString() == sourceHead, "Source manifest/head mismatch");
    JsonElement producer = binding.GetProperty("producerAssembly");
    VerifyMetadata(producer);
    Require(Path.GetFullPath(Environment.GetCommandLineArgs()[0]) == producer.GetProperty("path").GetString(),
        "Invoke the bound managed probe DLL directly through dotnet");
    JsonElement[] sources = binding.GetProperty("probeSources").EnumerateArray().ToArray();
    Require(sources.Length == 2 && sources.Count(source => Path.GetFileName(source.GetProperty("path").GetString()) == "Program.cs") == 1
        && sources.Count(source => Path.GetExtension(source.GetProperty("path").GetString()) == ".csproj") == 1,
        "Bind the actual Program.cs and selected project");
    foreach (JsonElement source in sources) VerifyMetadata(source);
    string[] expected = { "AngleSharp.Css.dll", "AngleSharp.dll", "OfficeIMO.Core.dll", "OfficeIMO.Html.AngleSharp.dll",
        "OfficeIMO.Html.Core.dll", "OfficeIMO.Html.dll", "OfficeIMO.Pdf.dll" };
    JsonElement[] modules = binding.GetProperty("runtimeDlls").EnumerateArray().ToArray();
    Require(modules.Length == expected.Length && modules.Select(module => Path.GetFileName(module.GetProperty("path").GetString()))
        .OrderBy(name => name, StringComparer.Ordinal).SequenceEqual(expected), "Bind exactly the seven deployed renderer DLLs");
    foreach (JsonElement module in modules) {
        VerifyMetadata(module);
        Require(Path.GetDirectoryName(module.GetProperty("path").GetString()) == Path.TrimEndingDirectorySeparator(AppContext.BaseDirectory),
            "Renderer DLL must be the actual deployed file beside the managed probe");
    }
}

sealed record SceneItem(HtmlRenderVisual Visual, OfficeTransform Transform, string Path, bool OwnsSource);
